/bin/zsh -lc "git diff -- grep.py && python3 - <<'PY'
from unittest.mock import mock_open, patch
from grep import grep

contents = {
    'a': 'Alpha\\nbeta\\nBeta\\n',
    'b': 'gamma\\nBeta\\n',
}

def opener(name, *args, **kwargs):
    return mock_open(read_data=contents[name])()

with patch('grep.open', side_effect=opener):
    checks = {
        'plain': grep('Beta', '', ['a']),
        'numbered': grep('beta', '-in', ['a']),
        'files': grep('beta', '-il', ['a', 'b']),
        'inverted_exact': grep('Beta', '-vx', ['a']),
    }
for name, value in checks.items():
    print(name + ':')
    print(repr(value))
PY"

